vector<vector<int>> kClosest(vector<vector<int>>& P, int k) {
    auto key = [](const vector<int>& p) { return make_tuple((long long)p[0] * p[0] + (long long)p[1] * p[1], p[0], p[1]); };
    partial_sort(P.begin(), P.begin() + k, P.end(), [&](auto& a, auto& b) { return key(a) < key(b); });
    return vector<vector<int>>(P.begin(), P.begin() + k);
}
